DROP TABLE IF EXISTS `bpi_transaction_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bpi_transaction_data` (
  `transaction_id` bigint NOT NULL,
  `card_holder_info` varchar(255) DEFAULT NULL,
  `card_holder_pan` varchar(255) DEFAULT NULL,
  `order_id` bigint DEFAULT NULL,
  `final_amount` bigint DEFAULT NULL,
  `reference_id` varchar(255) DEFAULT NULL,
  `response_code` int DEFAULT NULL,
  `reverse_send_time` bigint DEFAULT NULL,
  `sale_reference_id` bigint DEFAULT NULL,
  `settle_send_time` bigint DEFAULT NULL,
  `transaction_state` int DEFAULT NULL,
  `verify_send_time` bigint DEFAULT NULL,
  `sale_order_id` bigint DEFAULT NULL,
  PRIMARY KEY (`transaction_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
